mapper.update:
UPDATE ret_exchange SET status=#{nextStatus},approver_user_id=COALESCE(approver_user_id,#{approverUserId}),
  actual_refund_amount_minor=COALESCE(actual_refund_amount_minor,#{actualRefundAmountMinor}),
  actual_sale_receivable_minor=COALESCE(actual_sale_receivable_minor,#{actualSaleReceivableMinor}),
  actual_new_order_snapshot_sha256=COALESCE(actual_new_order_snapshot_sha256,#{actualNewOrderSnapshotSha256}),
  record_version=record_version+1,updated_at=#{updatedAt}
WHERE tenant_id=#{tenantId} AND exchange_id=#{exchangeId} AND status=#{expectedStatus}
  AND record_version=#{expectedVersion}
